package registry

var store = map[string]string{}

func Register(key, value string) {
	store[key] = value
}

func Lookup(key string) (string, bool) {
	v, ok := store[key]
	return v, ok
}

func Unregister(key string) {
	delete(store, key)
}

func Keys() []string {
	keys := make([]string, 0, len(store))
	for k := range store {
		keys = append(keys, k)
	}
	return keys
}

package registry

import "testing"

func TestRegisterLookup(t *testing.T) {
	store = map[string]string{} // reset global
	Register("a", "1")
	v, ok := Lookup("a")
	if !ok || v != "1" {
		t.Fatalf("want 1 true, got %q %v", v, ok)
	}
}

func TestUnregister(t *testing.T) {
	store = map[string]string{}
	Register("x", "v")
	Unregister("x")
	_, ok := Lookup("x")
	if ok {
		t.Fatal("x should be unregistered")
	}
}

func TestLookupMissing(t *testing.T) {
	store = map[string]string{}
	_, ok := Lookup("missing")
	if ok {
		t.Fatal("should not find missing key")
	}
}

