package registry

type Registry struct {
    store map[string]string
}

func NewRegistry() *Registry {
    return &Registry{store: make(map[string]string)}
}

func (r *Registry) Register(key, value string) { r.store[key] = value }
func (r *Registry) Lookup(key string) (string, bool) { v, ok := r.store[key]; return v, ok }
func (r *Registry) Unregister(key string) { delete(r.store, key) }
func (r *Registry) Keys() []string {
    keys := make([]string, 0, len(r.store))
    for k := range r.store { keys = append(keys, k) }
    return keys
}

